  const focus=auto?'Recovery':p.focus,recovery=focus==='Recovery',intensity={Light:.65,Normal:1,Intense:1.45}[p.intensity];
  const pace=p.learning*(p.traits.includes('Student')?1.1:1)*(p.traits.includes('Driven')&&p.intensity==='Intense'?1.12:1)*(p.traits.includes('PracticeAce')?1.15:1)*(p.traits.includes('Perfectionist')?1.05:1)*(p.squad==='academy'&&mentors.has(p.team)?1.05:1)*personality.reduce((v,t)=>v*((!t.focus||t.focus===focus)&&(!t.intensity||t.intensity===p.intensity)?t.pace||1:1),1);
  p.lastTraining=auto?'Auto-recovery':focus;
