export function dismissCelebration(s){s.celebration=null;}
export function bestOf(s){return s.phase==='regular'||['internationalQuarter','internationalPlayin'].includes(s.phase)&&s.event==='MSI'?3:5;}
function createSeries(s,a,b,interactive=false){const bo=bestOf(s);return {a,b,opponent:b,bestOf:bo,target:Math.floor(bo/2)+1,score:[0,0],games:[],current:null,done:false,won:null,decisionGames:s.phase==='regular'?(rng(s)<.12?[1,2]:[1]):null,interactive};}
function startSeriesGame(s,m){const number=m.games.length+1;let count=m.interactive?(s.phase==='regular'?(m.decisionGames.includes(number)?1:0):2):0;if(m.legacy)count=1;const events=[];while(events.length<count){const i=Math.floor(rng(s)*EVENTS.length);if(!events.includes(i))events.push(i);}events.sort((a,b)=>Number(EVENTS[a].time.replace(':',''))-Number(EVENTS[b].time.replace(':','')));m.current={number,events,modes:events.map(()=>rollMomentMode(s)),cursor:0,edge:0,calls:[]};if(!count)resolveSeriesGame(s,m);}
export function enterMatchday(s){ensureMeta(s);if(s.match||s.clubEvent||s.celebration||['draft','offseason'].includes(s.phase))return false;if(s.phase==='internationalGroups')return resolveWorldsGroups(s);training(s);const pair=userPair(s);if(!pair){finishMatchday(s);return true;}const reunion=beforeSecretMatch(s,opponent(s));s.match=createSeries(s,s.team,opponent(s),true);s.match.reunion=reunion;startSeriesGame(s,s.match);return true;}
export function nextSeriesGame(s){const m=s.match;if(!m||m.done||m.current)return false;startSeriesGame(s,m);return true;}
export function callDescriptor(s,kind){const m=s.match;if(kind==='risk')return m?.score[0]<m?.score[1]?'Comeback gamble':'High risk / high reward';if(kind==='steady')return 'Safe · smaller upside';return 'Calculated · moderate risk';}
export const momentWeight=ev=>ev.impact??({'08:40':.12,'19:20':.18,'29:10':.24,'14:25':.16,'23:15':.20,'33:40':.26}[ev.time]||.18);
export function callPreview(s,kind){const g=s.match?.current,ev=g&&EVENTS[g.events[g.cursor]];if(!ev)return null;const call=ev.calls.find(c=>c[2]===kind);if(!call)return null;const p=starters(s).find(p=>p.role===call[0]);let chance=.48+(effectiveSkill(p,'Macro')-50)*.002+(chemistry(s)-30)*.001+(kind==='steady'?.12:kind==='risk'?-.08:0);if(kind==='risk')chance+=(p.traits.includes('Playmaker')?.04:0)+(p.traits.includes('RiskTaker')?.03:0);if(kind==='steady'&&p.traits.includes('Patient'))chance+=.04;if(kind==='control'&&p.traits.includes('Improviser'))chance+=.04;const weight=momentWeight(ev),value={risk:20,control:12,steady:6}[kind];return {chance:clamp(chance,.3,.85),weight,up:value*weight,down:value*weight*(kind==='steady'?.5:.8),player:p,call};}
